<?php
include_once('class-teacher-utils.php');
function eya_ensure_tables($con){@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblearlyyearsskill (skillid INT NOT NULL AUTO_INCREMENT PRIMARY KEY,category VARCHAR(80) NOT NULL,skillname VARCHAR(160) NOT NULL,display_order INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active',UNIQUE KEY uq_eya_skill(skillname)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblearlyyearsassessment (assessmentid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,userid VARCHAR(60) NOT NULL,skillid INT NOT NULL,batchid VARCHAR(60) NOT NULL,termname INT NOT NULL,rating TINYINT NOT NULL,teachercomment VARCHAR(500) DEFAULT NULL,recordedby VARCHAR(60) NOT NULL,updatedat DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_eya_rating(userid,skillid,batchid,termname),KEY idx_eya_student(userid,batchid,termname)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$defaults=array(array('Personal & Social Development','Works independently',10),array('Personal & Social Development','Cooperates and shares',20),array('Communication & Language','Listens and follows instructions',30),array('Communication & Language','Expresses ideas clearly',40),array('Literacy','Recognises letters and sounds',50),array('Literacy','Enjoys books and storytelling',60),array('Numeracy','Recognises numbers and quantities',70),array('Numeracy','Solves simple practical problems',80),array('Creative & Physical Development','Uses drawing and fine-motor skills',90),array('Creative & Physical Development','Participates confidently in play',100));$stmt=mysqli_prepare($con,'INSERT IGNORE INTO tblearlyyearsskill(category,skillname,display_order) VALUES(?,?,?)');foreach($defaults as $item){mysqli_stmt_bind_param($stmt,'ssi',$item[0],$item[1],$item[2]);mysqli_stmt_execute($stmt);}if($stmt)mysqli_stmt_close($stmt);}
function eya_safe($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function eya_csrf(){if(empty($_SESSION['eya_csrf']))$_SESSION['eya_csrf']=bin2hex(random_bytes(32));return $_SESSION['eya_csrf'];}
function eya_admin(){return isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE'])&&$_SESSION['ACCESSLEVEL']==='administrator'&&in_array($_SESSION['SYSTEMTYPE'],array('normal_user','super_user'),true);}
?>
